import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { expect, expectTypeOf, it } from 'vitest';
import {
  TRIAL_BUILDINGS, SOCIETY_BUILDINGS, LAW_CATALOG, LAW_TRIAL, LAW_MESSAGES, RESEARCH_TOPICS,
  OUTSIDE_PLOTS, ORDER_TRIAL, GARRISON_TRIAL, CRIME_TRIAL, CRISIS_TRIAL, SOCIETY_TRIAL, DIFFICULTY_TRIAL, PURSE_TRIAL,
  GOODS_STOCK_TRIAL, TILE_TRIAL_BALANCE, IMMIGRATION_TRIAL_DEFAULTS, OUTSIDE_TRIAL,
  RING4_TRIAL, RETAINERS_HALL_TRIAL, SOCIETY_RING4_PLOTS,
  NPC_ORIGINS, NPC_HOBBIES, P7A_TRIAL,
} from '../index.js';

const cases = [
  { file: 'buildings.json', validator: 'validateBuildings', view: () => ({ trial: TRIAL_BUILDINGS, society: SOCIETY_BUILDINGS }),
    path: ['trial', 'hospital', 'upkeepMilli'], wrong: -1, message: 'buildings.json#hospital.upkeepMilli: expected integer >= 0' },
  { file: 'laws.json', validator: 'validateLaws', view: () => ({ catalog: LAW_CATALOG, trial: LAW_TRIAL, messages: LAW_MESSAGES }),
    path: ['catalog', 'curfew', 'name'], wrong: 7, message: 'laws.json#curfew.name: expected nonempty string' },
  { file: 'research.json', validator: 'validateResearch', view: () => RESEARCH_TOPICS,
    path: ['0', 'id'], wrong: 'unknown', message: 'research.json#unknown.id: expected deep-mining' },
  { file: 'outside-plots.json', validator: 'validateOutsidePlots', view: () => OUTSIDE_PLOTS,
    path: ['0', 'ring'], wrong: 0, message: 'outside-plots.json#field-1.ring: expected 1 | 2 | 3' },
  { file: 'tuning.json', validator: 'validateTuning', view: () => ({
      ORDER_TRIAL, GARRISON_TRIAL, CRIME_TRIAL, CRISIS_TRIAL, SOCIETY_TRIAL, GOODS_STOCK_TRIAL, TILE_TRIAL_BALANCE,
      IMMIGRATION_TRIAL_DEFAULTS, OUTSIDE_TRIAL, RING4_TRIAL, RETAINERS_HALL_TRIAL, SOCIETY_RING4_PLOTS,
      DIFFICULTY_TRIAL, PURSE_TRIAL: Object.freeze({
        marker: PURSE_TRIAL.marker,
        levyMaxPercent: PURSE_TRIAL.levyMaxPercent,
        levyFreePercent: PURSE_TRIAL.levyFreePercent,
        levySatisfactionPerPoint: PURSE_TRIAL.levySatisfactionPerPoint,
        donateSatisfactionPerGoldMilli: PURSE_TRIAL.donateSatisfactionPerGoldMilli,
        donateSatisfactionCapPerWeek: PURSE_TRIAL.donateSatisfactionCapPerWeek,
      }),
    }),
    path: ['ORDER_TRIAL', 'newGame', 'security'], wrong: -1, message: 'tuning.json#ORDER_TRIAL.newGame.security: expected integer >= 0' },
  { file: 'npc-life.json', validator: 'validateNpcLife', view: () => ({ origins: NPC_ORIGINS, hobbies: NPC_HOBBIES, P7A_TRIAL }),
    path: ['origins', 'frontier', 'name'], wrong: 7, message: 'npc-life.json#frontier.name: expected nonempty string' },
] as const;

function data(file: string): unknown {
  return JSON.parse(readFileSync(new URL(`../data/${file}`, import.meta.url), 'utf8'));
}
async function validators() {
  const path = '../data/validate.js';
  return await import(path) as typeof import('../data/validate.js');
}

it.each(cases)('$file validates to the unchanged typed views', async entry => {
  const api = await validators();
  expect(api[entry.validator](data(entry.file))).toEqual(entry.view());
});

it.each(cases)('$file rejects one wrong field with the exact CatalogError message', async entry => {
  const api = await validators();
  const copy = data(entry.file) as Record<string, unknown>;
  let target = copy;
  for (const key of entry.path.slice(0, -1)) target = target[key] as Record<string, unknown>;
  target[entry.path[entry.path.length - 1]] = entry.wrong;
  let thrown: unknown;
  try { api[entry.validator](copy); } catch (error) { thrown = error; }
  expect(thrown).toBeInstanceOf(api.CatalogError);
  expect((thrown as Error).message).toBe(entry.message);
});

it.each(cases)('$file rejects a missing root entry', async entry => {
  const api = await validators();
  const copy = data(entry.file) as Record<string, unknown>;
  delete copy[Object.keys(copy)[0]];
  expect(() => api[entry.validator](copy)).toThrow(api.CatalogError);
});

it.each(cases)('$file has recursively frozen typed views', entry => {
  function frozen(value: unknown) {
    if (value && typeof value === 'object') {
      expect(Object.isFrozen(value)).toBe(true);
      Object.values(value).forEach(frozen);
    }
  }
  // Wrapper objects belong to the test; the public constants themselves are frozen.
  const view = entry.view();
  if (Array.isArray(view)) frozen(view);
  else Object.values(view).forEach(frozen);
});

it('validates the acquisition TRIAL data and pins malformed bands with a named error', async () => {
  const api = await validators();
  const source = data('npc-acquisition.json');
  expect(api.validateNpcAcquisition(source)).toStrictEqual(source);
  const bad = structuredClone(source) as { AUCTION_TRIAL: { steadyBps: number } };
  bad.AUCTION_TRIAL.steadyBps = 12_000;
  let thrown: unknown;
  try { api.validateNpcAcquisition(bad); } catch (error) { thrown = error; }
  expect(thrown).toBeInstanceOf(api.CatalogError);
  expect((thrown as Error).message).toBe('npc-acquisition.json#AUCTION_TRIAL.ceilingBps: expected opening <= floor < steady < keen <= ceiling');
});

it.each([
  ['openingStepMilli', 0],
  ['rivalStepMilli', 0],
  ['playerRaisesMilli', 0],
  ['playerRaisesMilli', 1],
] as const)('names the malformed whole-Gold step %s at index %i', async (field, index) => {
  const api = await validators();
  const bad = data('npc-acquisition.json') as {
    AUCTION_TRIAL: Record<'openingStepMilli' | 'rivalStepMilli', number> & { playerRaisesMilli: number[] };
  };
  if (field === 'playerRaisesMilli') bad.AUCTION_TRIAL[field][index] += 1;
  else bad.AUCTION_TRIAL[field] += 1;
  let thrown: unknown;
  try { api.validateNpcAcquisition(bad); } catch (error) { thrown = error; }
  const path = field === 'playerRaisesMilli' ? field + '[' + index + ']' : field;
  expect(thrown).toBeInstanceOf(api.CatalogError);
  expect((thrown as Error).message).toBe('npc-acquisition.json#AUCTION_TRIAL.' + path + ': expected whole Gold steps');
});

it('preserves the original vote message literal type', () => {
  expectTypeOf(LAW_MESSAGES.VOTE_SHORT).toEqualTypeOf<'The vote would fail: For {F} · Against {A}.'>();
});

// SHA-256 of JSON.stringify for each approved catalog value.
// Unchanged catalog entries keep their hashes from 5cc2522f27e01b49baaa6e44bba01904edcea5c0.
const pinnedCatalogs = [
